const now = new Date();
const timestamp = now.toISOString();

// Get the agent output
const agentOutput = $input.first().json;
const agentResponse = agentOutput.output || '';
const userMessage = agentOutput.chatInput || '';

// Simple intent detection from the agent response
let intent = 'unknown';
const responseLower = agentResponse.toLowerCase();
const messageLower = userMessage.toLowerCase();

if (messageLower.includes('free') || messageLower.includes('available') || messageLower.includes('busy') || messageLower.includes('slobodn')) {
  intent = 'check_availability';
} else if (messageLower.includes('schedule') || messageLower.includes('add') || messageLower.includes('create') || messageLower.includes('book') || messageLower.includes('zakaži') || messageLower.includes('dodaj')) {
  intent = 'add_event';
} else if (messageLower.includes('what do i have') || messageLower.includes('show') || messageLower.includes('list') || messageLower.includes('schedule') || messageLower.includes('events') || messageLower.includes('raspored')) {
  intent = 'list_events';
} else if (messageLower.match(/^(yes|da|sure|go ahead|confirm|potvrdi)/i)) {
  intent = 'confirm_event';
}

// Determine action taken
let action = 'responded';
if (responseLower.includes('created') || responseLower.includes('scheduled') || responseLower.includes('booked')) {
  action = 'event_created';
} else if (responseLower.includes('shall i') || responseLower.includes('go ahead') || responseLower.includes('confirm')) {
  action = 'awaiting_confirmation';
} else if (intent === 'check_availability') {
  action = 'checked_availability';
} else if (intent === 'list_events') {
  action = 'listed_events';
}

return [{
  json: {
    timestamp: timestamp,
    user_message: userMessage.substring(0, 500),
    intent: intent,
    action: action,
    success: 'true',
    agent_response: agentResponse.substring(0, 1000)
  }
}];
